import { useEffect, useRef, useState } from 'react';
import { supabase } from '../config/supabase';

export const useMultiplayer = (roomId = 'global-space', onPlayerUpdate, onPlayerLeave) => {
    const channelRef = useRef(null);
    const [isConnected, setIsConnected] = useState(false);

    useEffect(() => {
        // Create a unique user ID for this session
        const userId = 'player_' + Math.random().toString(36).substr(2, 9);
        
        // Initialize the channel
        const channel = supabase.channel(`room:${roomId}`, {
            config: {
                presence: { key: userId },
            }
        });

        // Listen for presence changes (join/leave)
        channel.on('presence', { event: 'sync' }, () => {
            const newState = channel.presenceState();
            // Optional: Handle full sync of all users if needed
        });

        channel.on('presence', { event: 'join' }, ({ key, newPresences }) => {
            console.log('Player joined:', key);
        });

        channel.on('presence', { event: 'leave' }, ({ key, leftPresences }) => {
            console.log('Player left:', key);
            if (onPlayerLeave) onPlayerLeave(key);
        });

        // Listen for broadcast messages (high frequency position updates)
        channel.on('broadcast', { event: 'pos' }, ({ payload }) => {
            if (payload.userId !== userId && onPlayerUpdate) {
                onPlayerUpdate(payload.userId, payload.data);
            }
        });

        channel.subscribe(async (status) => {
            if (status === 'SUBSCRIBED') {
                setIsConnected(true);
                // Track our presence
                await channel.track({ online_at: new Date().toISOString() });
            } else {
                setIsConnected(false);
            }
        });

        channelRef.current = channel;

        return () => {
            if (channelRef.current) {
                supabase.removeChannel(channelRef.current);
            }
        };
    }, [roomId, onPlayerUpdate, onPlayerLeave]);

    const broadcastPosition = (data) => {
        if (isConnected && channelRef.current) {
            channelRef.current.send({
                type: 'broadcast',
                event: 'pos',
                payload: { data }
            });
        }
    };

    return { isConnected, broadcastPosition };
};
